const DIGITS: Str = "0123456789"

pub fn add_decimal(a: Str, b: Str) -> Str {
  let xs = a.codes()
  let ys = b.codes()
  var i = xs.len() - 1
  var j = ys.len() - 1
  var carry = 0
  var digits: List[Str] = []
  while i >= 0 or j >= 0 or carry > 0 {
    var total = carry
    if i >= 0 {
      total = total + xs.get_or(i, 48) - 48
    }
    if j >= 0 {
      total = total + ys.get_or(j, 48) - 48
    }
    let d = total % 10
    digits = digits.push(DIGITS.slice(d, d + 1))
    carry = total / 10
    i = i - 1
    j = j - 1
  }
  if digits.is_empty() {
    return "0"
  }
  var out = digits.reverse().join("")
  while out.len() > 1 and out.slice(0, 1) == "0" {
    out = out.slice(1, out.len())
  }
  return out
}
